using System;using System.Collections.Generic;using System.Linq;using System.Numerics;using Clipper2Lib;
namespace RoadRush.TerrainDraft {
 public sealed class ProtectedBandClassifier {
  readonly Dictionary<(long,long),bool> pointCache=new Dictionary<(long,long),bool>();readonly List<(long X0,long Z0,long X1,long Z1)> bounds=new List<(long,long,long,long)>();readonly Paths64 band;readonly long ox,oz;readonly List<(Point64 A,Point64 B)> edges=new List<(Point64,Point64)>();readonly Dictionary<(int,int),List<int>> grid=new Dictionary<(int,int),List<int>>();readonly int workCap;int work;
  public ProtectedBandClassifier(Paths64 originalBand,long originX,long originZ,int totalWorkCap=20000000){if(originalBand==null||originalBand.Sum(p=>p.Count)>4096||totalWorkCap<1)throw new TerrainBudgetException("Protectedband classifier inputcap");band=new Paths64(originalBand.Select(p=>new Path64(p)));ox=originX;oz=originZ;workCap=totalWorkCap;foreach(var ring in band)bounds.Add((ring.Min(p=>p.X),ring.Min(p=>p.Y),ring.Max(p=>p.X),ring.Max(p=>p.Y)));foreach(var ring in band)for(int i=0;i<ring.Count;i++){var a=ring[i];var b=ring[(i+1)%ring.Count];int id=edges.Count;edges.Add((a,b));int x0=Cell(Math.Min(a.X,b.X),ox),x1=Cell(Math.Max(a.X,b.X),ox),z0=Cell(Math.Min(a.Y,b.Y),oz),z1=Cell(Math.Max(a.Y,b.Y),oz);for(int z=z0;z<=z1;z++)for(int x=x0;x<=x1;x++){if(!grid.TryGetValue((x,z),out var list))grid[(x,z)]=list=new List<int>();list.Add(id);Check();}}}
  static int Cell(long p,long origin)=>(int)Math.Floor((double)(p-origin)/ManagedTerrainDomainLocal.Scale);
  void Check(){if(++work>workCap)throw new TerrainBudgetException("Protectedband classifier workcap");}
  static BigInteger Cross(Point64 a,Point64 b,Point64 c)=>(BigInteger)(b.X-a.X)*(c.Y-a.Y)-(BigInteger)(b.Y-a.Y)*(c.X-a.X);
  bool Inside(Point64 p){Check();var key=(p.X,p.Y);if(pointCache.TryGetValue(key,out bool result))return result;bool value=false;for(int i=0;i<band.Count;i++){var box=bounds[i];if(p.X<box.X0||p.X>box.X1||p.Y<box.Z0||p.Y>box.Z1)continue;var ring=band[i];work+=ring.Count;if(work>workCap)throw new TerrainBudgetException("Protectedband pointclassification workcap");var v=Clipper.PointInPolygon(p,ring);if(v==PointInPolygonResult.IsOn){value=true;break;}if(v==PointInPolygonResult.IsInside)value=!value;}if(pointCache.Count>=100000)throw new TerrainBudgetException("Protectedband pointcache cap");pointCache.Add(key,value);return value;}
  static bool Triangle(Point64 p,Point64 a,Point64 b,Point64 c){int x=Cross(a,b,p).Sign,y=Cross(b,c,p).Sign,z=Cross(c,a,p).Sign;return(x>=0&&y>=0&&z>=0)||(x<=0&&y<=0&&z<=0);}
  static bool Meet(Point64 a,Point64 b,Point64 c,Point64 d){if(Math.Max(a.X,b.X)<Math.Min(c.X,d.X)||Math.Max(c.X,d.X)<Math.Min(a.X,b.X)||Math.Max(a.Y,b.Y)<Math.Min(c.Y,d.Y)||Math.Max(c.Y,d.Y)<Math.Min(a.Y,b.Y))return false;return Cross(a,b,c).Sign*Cross(a,b,d).Sign<=0&&Cross(c,d,a).Sign*Cross(c,d,b).Sign<=0;}
  public byte Classify(TerrainPoint pa,TerrainPoint pb,TerrainPoint pc){long s=ManagedTerrainDomainLocal.Scale;Point64 P(TerrainPoint p)=>new Point64(ox+(long)Math.Round(p.X*s),oz+(long)Math.Round(p.Z*s));var a=P(pa);var b=P(pb);var c=P(pc);if(Inside(a)||Inside(b)||Inside(c))return 1;int x0=Cell(Math.Min(a.X,Math.Min(b.X,c.X)),ox),x1=Cell(Math.Max(a.X,Math.Max(b.X,c.X)),ox),z0=Cell(Math.Min(a.Y,Math.Min(b.Y,c.Y)),oz),z1=Cell(Math.Max(a.Y,Math.Max(b.Y,c.Y)),oz);var seen=new HashSet<int>();for(int z=z0;z<=z1;z++)for(int x=x0;x<=x1;x++)if(grid.TryGetValue((x,z),out var list))foreach(int id in list)if(seen.Add(id)){Check();var e=edges[id];if(Triangle(e.A,a,b,c)||Meet(a,b,e.A,e.B)||Meet(b,c,e.A,e.B)||Meet(c,a,e.A,e.B))return 1;}return 2;}
 }
}
